import{_ as e,o as l,c as t,a2 as n}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"Install Ollama","description":"Install Ollama on Windows / macOS / Linux and enable the OpenAI-compatible API (11434) for MiniTavern over LAN.","frontmatter":{"title":"Install Ollama","description":"Install Ollama on Windows / macOS / Linux and enable the OpenAI-compatible API (11434) for MiniTavern over LAN.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Install Ollama · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Install Ollama on Windows / macOS / Linux and enable the OpenAI-compatible API (11434) for MiniTavern over LAN."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/ollama/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/ollama/install"}]]},"headers":[],"relativePath":"en/ollama/install.md","filePath":"en/ollama/install.md","lastUpdated":1787224147000}'),i={name:"en/ollama/install.md"};function s(o,a,r,d,p,h){return l(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="install-ollama" tabindex="-1">Install Ollama <a class="header-anchor" href="#install-ollama" aria-label="Permalink to &quot;Install Ollama&quot;">​</a></h1><p>Ollama runs models on your PC and exposes an <strong>OpenAI-compatible</strong> HTTP API (default port <code>11434</code>).</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li>Open <a href="https://ollama.com/download" target="_blank" rel="noreferrer">https://ollama.com/download</a> and download the Windows installer.</li><li>Install and start Ollama (tray icon should appear).</li><li>Open <strong>Command Prompt</strong> or <strong>PowerShell</strong>:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>A version number means install succeeded.</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><ol><li>Download the macOS build from <a href="https://ollama.com/download" target="_blank" rel="noreferrer">https://ollama.com/download</a> and drag it into Applications.</li><li>On first launch, allow network permission.</li><li>Open Terminal:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="verify-the-local-api" tabindex="-1">Verify the local API <a class="header-anchor" href="#verify-the-local-api" aria-label="Permalink to &quot;Verify the local API&quot;">​</a></h2><p>With the service running, open in the PC browser:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:11434</span></span></code></pre></div><p>Or in a terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:11434/api/tags</span></span></code></pre></div><p>JSON (model list, possibly empty) means the API is listening.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./models">Download and pick models</a></li><li><a href="./lan">Enable LAN access</a> (required for phone → PC)</li></ul>',17)])])}const u=e(i,[["render",s]]);export{m as __pageData,u as default};
